package main

import (
	"fmt"
	"math/rand"
	"os"
	"sort"
)

var groupCost = [6]int{0, 800, 1520, 2160, 2560, 3000}

// unrestricted: a group may be any non-empty subset of distinct titles.
// This is definitely complete (any grouping can be ordered some way).
func costUnrestricted(counts [5]int, memo map[[5]int]int) int {
	if v, ok := memo[counts]; ok {
		return v
	}
	if counts[0]+counts[1]+counts[2]+counts[3]+counts[4] == 0 {
		return 0
	}
	best := -1
	for mask := 1; mask < 32; mask++ {
		g := 0
		next := counts
		ok := true
		for i := 0; i < 5; i++ {
			if mask&(1<<i) != 0 {
				if counts[i] == 0 {
					ok = false
					break
				}
				next[i]--
				g++
			}
		}
		if !ok {
			continue
		}
		sort.Ints(next[:])
		c := groupCost[g] + costUnrestricted(next, memo)
		if best == -1 || c < best {
			best = c
		}
	}
	memo[counts] = best
	return best
}

// topG: a group is always formed from the g most-counted titles.
func costTopG(counts [5]int, memo map[[5]int]int) int {
	if v, ok := memo[counts]; ok {
		return v
	}
	if counts[4] == 0 {
		return 0
	}
	best := -1
	for g := 1; g <= 5; g++ {
		if counts[5-g] == 0 {
			break
		}
		next := counts
		for i := 5 - g; i < 5; i++ {
			next[i]--
		}
		sort.Ints(next[:])
		c := groupCost[g] + costTopG(next, memo)
		if best == -1 || c < best {
			best = c
		}
	}
	memo[counts] = best
	return best
}

// greedy: the classic sort + "prefer 4 over 5" rule.
func costGreedy(counts [5]int) int {
	sort.Ints(counts[:]) // ascending
	total := 0
	for counts[4] > 0 {
		distinct := 0
		for _, c := range counts {
			if c > 0 {
				distinct++
			}
		}
		g := distinct
		// c3 > c4 with both c4,c5 > 0 means a group of 5 would strand a group of 3
		if counts[4] > 0 && counts[2] > counts[3] {
			g = 4
		}
		total += groupCost[g]
		for i := 5 - g; i < 5; i++ {
			counts[i]--
		}
		sort.Ints(counts[:])
	}
	return total
}

func main() {
	maxCount := 10
	seed := int64(1)
	if len(os.Args) > 1 {
		fmt.Sscanf(os.Args[1], "%d", &maxCount)
	}
	rng := rand.New(rand.NewSource(seed))
	memoU := make(map[[5]int]int)
	memoT := make(map[[5]int]int)
	n := 200000
	badU, badG := 0, 0
	for i := 0; i < n; i++ {
		var c [5]int
		for k := 4; k >= 0; k-- {
			c[k] = rng.Intn(maxCount + 1)
		}
		sort.Ints(c[:])
		u := costUnrestricted(c, memoU)
		t := costTopG(c, memoT)
		gr := costGreedy(c)
		if u != t {
			badU++
			if badU < 10 {
				fmt.Printf("TOPG MISMATCH %v unrestricted=%d topg=%d\n", c, u, t)
			}
		}
		if u != gr {
			badG++
			if badG < 10 {
				fmt.Printf("GREEDY MISMATCH %v unrestricted=%d greedy=%d\n", c, u, gr)
			}
		}
	}
	fmt.Printf("maxCount=%d n=%d topG mismatches=%d greedy mismatches=%d\n", maxCount, n, badU, badG)
}

